// Command openapi writes the OpenAPI description of Savorum's HTTP API from
// the running handler definitions, so the published document is generated by
// the same code that serves the requests rather than maintained beside it.
// --check verifies the committed document still matches, which is what CI runs.
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"os"

	"github.com/danielgtaylor/huma/v2"

	"github.com/savorum/savorum/internal/automation"
	"github.com/savorum/savorum/internal/event"
	"github.com/savorum/savorum/internal/pantry"
	"github.com/savorum/savorum/internal/webhook"

	api "github.com/savorum/savorum/internal/api/v1"
	"github.com/savorum/savorum/internal/codegen"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(arguments []string) error {
	flags := flag.NewFlagSet("openapi", flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	output := flags.String("output", "api/openapi.json", "OpenAPI output path")

	check := flags.Bool("check", false, "verify that the output file is current")
	if err := flags.Parse(arguments); err != nil {
		return fmt.Errorf("parse command flags: %w", err)
	}

	if flags.NArg() != 0 {
		return fmt.Errorf("unexpected argument %q", flags.Arg(0))
	}

	definition, err := schemaDefinition()
	if err != nil {
		return err
	}

	encoded, err := json.MarshalIndent(definition.OpenAPI(), "", "  ")
	if err != nil {
		return fmt.Errorf("encode OpenAPI schema: %w", err)
	}

	encoded = append(encoded, '\n')
	if *check {
		return codegen.CheckArtifact(*output, encoded, "go run ./cmd/openapi")
	}

	return codegen.WriteArtifact(*output, encoded)
}

// schemaDefinition registers every operation, including those whose services
// are optional at run time, so the document describes the complete API.
func schemaDefinition() (huma.API, error) {
	_, definition, err := api.New(schemaService{}, schemaHealth{}, schemaPrinter{}, api.Options{
		Selection:     schemaSelections{},
		Automation:    &automation.Service{},
		Webhooks:      &webhook.Service{},
		Events:        schemaEvents{},
		Pantry:        schemaPantry{},
		Assets:        schemaService{},
		Configuration: schemaConfiguration{},
		Preferences:   schemaPreferences{},
		ImportJobs:    schemaImportJobs{},
		Meals:         schemaMealService{},
		Shopping:      schemaShoppingService{},
		MealCalendar:  schemaMealCalendarService{},
	})
	if err != nil {
		return nil, fmt.Errorf("construct API schema: %w", err)
	}

	api.RegisterStorageStatus(definition, nil)
	api.RegisterConnect(definition, nil, true)

	return definition, nil
}

type schemaPantry struct{}

func (schemaPantry) PantryEntries(context.Context) ([]pantry.Entry, error) { return nil, nil }
func (schemaPantry) SavePantryEntry(context.Context, pantry.Entry, uint64) (pantry.Entry, error) {
	return pantry.Entry{}, nil
}
func (schemaPantry) DeletePantryEntry(context.Context, string, uint64) error { return nil }

type schemaEvents struct{}

func (schemaEvents) ReadEvents(context.Context, string, int) (event.Page, error) {
	return event.Page{}, nil
}

type schemaSelections struct{ api.SelectionService }
